export const GLOSSARY_SHARD = Object.freeze({"all-time-high":{"slug":"all-time-high","cat":"basics","en":"All-time high (ATH)","contentLocale":"zh-Hans","term":"历史最高价（ATH）","aka":["ATH","All-time high","历史新高"],"short":"历史最高价（ATH，All-Time High）是某个资产自上市交易以来曾达到的最高价格，创新高即价格突破这一纪录。","body":["ATH 常被用来衡量一个币距离巅峰还有多远。行情网站通常会显示“距 ATH 跌了多少”，比如某币当前价格只有 ATH 的 20%，就是“较 ATH 下跌 80%”。对应的历史最低价叫 ATL（All-Time Low）。",["价格接近或突破 ATH 时，市场情绪往往最热，因为之前所有买家都处于盈利状态，上方没有被套盘的卖压。但这也是 ",["FOMO","fomo"]," 最强、波动最大的阶段。"],["注意不同",["交易所","centralized-exchange"],"、不同",["交易对","trading-pair"],"记录的 ATH 可能略有差别，特别是在极端行情中某个平台出现瞬间插针时。看 ATH 数据时最好以主流数据平台的综合价格为准。"]],"example":["假设某币的 ATH 是 12 ",["USDT","usdt"],"，现在价格 3 USDT，那么它较 ATH 下跌了 (12 − 3) ÷ 12 = 75%。很多人会觉得“只要涨回 ATH 就能赚 4 倍”，但从 3 涨到 12 需要上涨 300%。许多",["山寨币","altcoin"],"在上一轮周期创下 ATH 后，再也没有回到那个价格。"],"mistakes":["以为价格跌离 ATH 很多就一定会涨回去。","在创新高的瞬间用全部资金追入，忽视了高位剧烈波动。","比较不同平台的 ATH 数据，误以为数据有错。"],"faq":[{"q":"ATH 是什么意思？","a":"ATH 是 All-Time High 的缩写，意为历史最高价。相对的 ATL 是 All-Time Low，即历史最低价。"},{"q":"币价创 ATH 后会继续涨吗？","a":"无法确定。突破新高后既可能继续上涨，也可能很快回落，ATH 只是一个历史纪录，不是预测信号。"}],"title":"ATH 是什么意思？历史最高价的含义","description":"ATH（历史最高价）在币圈是什么意思？讲清距 ATH 跌幅怎么算、跌 75% 后需要涨多少才能回到高点，以及创新高时的风险。","related":[["bull-market","牛市（Bull Market）","牛市是指加密货币或其他资产价格在较长时间内持续上涨、成交活跃、市场情绪普遍乐观的阶段，与之相对的是熊市。"],["fomo","FOMO（错失恐惧）","FOMO（Fear of Missing Out）指害怕错过上涨行情而冲动买入的心理，在币圈常表现为追高和临时加仓。"],["volatility","波动率（Volatility）","波动率是衡量资产价格在一段时间内上下变动幅度的指标，波动率越高，价格涨跌越剧烈，加密货币通常远高于股票和外汇。"],["support-and-resistance","支撑位与阻力位（Support and Resistance）","支撑位是价格下跌时多次止跌反弹的价格区域，阻力位（也叫压力位）是价格上涨时多次受阻回落的区域，交易者用它们规划入场、止损和止盈。"]],"lesson":null,"coin":null,"tool":"/coins","cta":false},"coin-margined-futures":{"slug":"coin-margined-futures","cat":"derivatives","en":"Coin-margined (inverse) futures","contentLocale":"zh-Hans","term":"币本位合约（Coin-Margined Futures）","aka":["币本位","反向合约","inverse futures"],"short":"币本位合约是用 BTC、ETH 等加密货币本身作为保证金并结算盈亏的合约，也叫反向合约，盈亏以币计价，而不是以 USDT 计价。","body":[["在币本位合约里，你存入的是 ",["BTC","bitcoin"],"，赚到或亏掉的也是 BTC。合约面值通常以美元标价，比如每张 BTC 合约面值 100 美元（具体以",["交易所","centralized-exchange"],"为准），因此盈亏在币的数量上是非线性的：同样涨跌 10%，赚到和亏掉的 BTC 数量并不对称。"],["币本位适合本来就持有大量币、想以币为单位计算收益的人，比如矿工和长期持币者。持有 1 BTC 的人开 1 倍空单，可以把账户的美元价值大致锁定，同时不需要卖出 BTC 换成",["稳定币","stablecoin"],"。"],["币本位的风险在于“双重暴露”：开多时价格下跌，你的仓位亏损，同时作为保证金的 BTC 本身也在贬值，",["强平","liquidation"],"会来得更快。很多新手更习惯 U 本位，因为盈亏直接以 ",["USDT","usdt"]," 显示，更直观。"]],"example":"假设 BTC 价格 60,000 美元，你用 1 BTC 作保证金，开 600 张面值 100 美元的多单，合约价值 60,000 美元。价格涨到 66,000 时，盈利 = 60,000 × (1/60,000 − 1/66,000) ≈ 0.0909 BTC，按 66,000 折合约 6,000 美元。账户里的 BTC 变成约 1.0909 枚，币和美元价值都增加了。","mistakes":["用 U 本位的线性思维计算币本位盈亏，算错收益和强平价。","开币本位多单时忽略保证金本身也在随行情贬值。","以为币本位和 U 本位只是显示单位不同，没注意合约面值和计算方式不同。"],"faq":[{"q":"币本位和 U 本位有什么区别？","a":"币本位用币作保证金、以币结算，盈亏是非线性的；U 本位用 USDT 作保证金、以 USDT 结算，盈亏是线性的，更直观。"},{"q":"为什么叫反向合约？","a":"因为盈亏按“1 ÷ 价格”的方式计算，合约以美元计价但用币结算，与 U 本位的正向（线性）合约相反。"}],"title":"币本位合约是什么？反向合约与 U 本位区别","description":"解释币本位合约（反向合约）如何用 BTC 等币作保证金、盈亏为何是非线性的，以及它与 U 本位合约的区别和适用人群。","related":[["usdt-margined-futures","U本位合约（USDT-Margined Futures）","U本位合约是以 USDT 等稳定币作为保证金并结算盈亏的合约，也叫正向或线性合约，盈亏直接以 USDT 计算，是新手最常用的合约类型。"],["perpetual-futures","永续合约（Perpetual Futures）","永续合约是一种没有到期日的期货合约，可以无限期持有，通过多空双方定期互付资金费率，让合约价格始终贴近现货价格。"],["unrealized-pnl","未实现盈亏（Unrealized PnL）","未实现盈亏是仓位尚未平仓时，按当前价格（合约中通常是标记价格）计算出的账面盈利或亏损，只有平仓后才变成已实现盈亏。"],["hedging","对冲（Hedging）","对冲是建立一个与现有持仓方向相反或相关的仓位，用来抵消部分价格波动风险的做法，例如持有现货的同时开合约空单。"]],"lesson":{"id":"E18","slug":"spot-vs-futures","ep":18,"title":"现货和合约，买到的不是同一件事"},"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"hedging":{"slug":"hedging","cat":"derivatives","en":"Hedging","contentLocale":"zh-Hans","term":"对冲（Hedging）","aka":["套期保值","风险对冲","hedge"],"short":"对冲是建立一个与现有持仓方向相反或相关的仓位，用来抵消部分价格波动风险的做法，例如持有现货的同时开合约空单。","body":[["最常见的加密对冲是期现对冲：手里有 ",["BTC","bitcoin"]," 现货，但短期担心下跌，又不想卖出，就在永续或",["交割合约","delivery-futures"],"上开等量或部分数量的空单。价格下跌时现货亏、空单赚；价格上涨时现货赚、空单亏，整体波动变小。"],["对冲有成本。",["永续合约","perpetual-futures"],"空单在正",["资金费率","funding-rate"],"时能收到资金费，在负费率时要付；交割合约的",["基差","futures-basis"],"会在开仓时锁定；期权对冲要付权利金。此外，对冲仓位本身需要保证金，如果保证金不足，空单在暴涨中可能被",["强平","liquidation"],"，对冲就失效了。"],"对冲的目的是降低风险，而不是增加收益。完全对冲后几乎没有方向盈亏，部分对冲则在保留一部分上涨空间的同时减少下跌损失，比例取决于你的需求。"],"example":"假设你持有 2 BTC 现货，价格 60,000 USDT，你担心短期回调，开了 1 BTC 的永续空单，对冲一半。如果 BTC 跌到 54,000，现货亏 12,000，空单赚 6,000，合计亏 6,000；如果涨到 66,000，现货赚 12,000，空单亏 6,000，合计赚 6,000。无论涨跌，波动都只剩一半，另外还要计算资金费和手续费。","mistakes":["对冲仓位杠杆过高，暴涨时空单被强平，现货却没保护到。","忽略长期持有永续空单可能产生的资金费成本。","开了对冲又频繁根据行情加减仓，结果变成了投机。"],"faq":[{"q":"对冲能完全消除风险吗？","a":"不能。对冲主要减少价格方向风险，但仍有资金费、基差变化、保证金不足被强平和交易所平台风险。"},{"q":"现货和合约怎么对冲？","a":"持有现货的同时，在合约上开数量相同或部分数量的空单。价格下跌时空单盈利抵消现货亏损，反之亦然。"}],"title":"对冲是什么意思？加密货币现货合约对冲","description":"解释加密货币中对冲（套期保值）的原理、如何用合约空单对冲现货、对冲的主要成本，以及对冲可能失效的几种情况。","related":[["short-selling","卖空（Short Selling）","卖空是先借入或通过合约卖出自己并不持有的资产，等价格下跌后再买回归还或平仓，从下跌中赚取差价的交易方式。"],["perpetual-futures","永续合约（Perpetual Futures）","永续合约是一种没有到期日的期货合约，可以无限期持有，通过多空双方定期互付资金费率，让合约价格始终贴近现货价格。"],["options","加密期权（Crypto Options）","加密期权是一种合约，买方支付权利金后，获得在到期日以约定行权价买入（看涨期权）或卖出（看跌期权）某种加密资产的权利，但没有义务。"],["portfolio-margin","组合保证金（Portfolio Margin）","组合保证金是一种按整个投资组合的净风险计算保证金的模式，现货、合约、期权的仓位可以互相抵消风险，对冲良好的组合所需保证金更低。"]],"lesson":{"id":"E18","slug":"spot-vs-futures","ep":18,"title":"现货和合约，买到的不是同一件事"},"coin":null,"tool":null,"cta":false},"options":{"slug":"options","cat":"derivatives","en":"Crypto options","contentLocale":"zh-Hans","term":"加密期权（Crypto Options）","aka":["期权","看涨期权","看跌期权","options"],"short":"加密期权是一种合约，买方支付权利金后，获得在到期日以约定行权价买入（看涨期权）或卖出（看跌期权）某种加密资产的权利，但没有义务。","body":[["期权有四个关键要素：标的（如 ",["BTC","bitcoin"],"）、行权价、到期日和权利金。买方最多亏掉权利金，收益取决于到期时价格超过行权价多少；卖方先收权利金，但可能承担较大的亏损，所以卖方需要缴纳保证金。"],["多数加密期权是欧式期权，只能在到期时行权，并且以现金结算差额。Deribit 是",["成交量","trading-volume"],"较大的加密期权",["交易所","centralized-exchange"],"之一，OKX、Bybit、Binance 等也提供期权产品。期权价格受标的价格、剩余时间和隐含",["波动率","volatility"],"影响，越临近到期，时间价值衰减越快。"],["期权常用于",["对冲","hedging"],"（比如持有现货时买入看跌期权当作保险），也用于表达对波动率的看法。交易所的",["双币投资","dual-investment"],"等理财产品，本质上往往包含卖出期权的结构，这也是它收益较高、却可能被“换币”的原因。"]],"example":"假设 BTC 价格 62,000 USDT，你花 1,500 USDT 买入一张 30 天后到期、行权价 65,000 的看涨期权（1 BTC）。到期时 BTC 为 70,000，你获得 70,000 − 65,000 = 5,000 USDT，扣除权利金净赚 3,500 USDT。如果到期时 BTC 低于 65,000，期权作废，你亏掉 1,500 USDT 权利金。盈亏平衡价是 66,500。","mistakes":["只看方向买期权，忽略即使方向对了，涨得不够多或太慢也会亏掉权利金。","把卖出期权当作稳定收租，低估极端行情下的亏损。","不理解隐含波动率，在波动率很高时买入昂贵的期权。"],"faq":[{"q":"期权和期货有什么区别？","a":"期货买卖双方都有义务按价格结算，盈亏对称；期权买方只有权利没有义务，最大亏损是权利金，卖方则承担义务。"},{"q":"买期权最多亏多少？","a":"期权买方最多亏掉支付的全部权利金，不会被强平；卖方的亏损则可能远大于收到的权利金。"}],"title":"加密期权是什么？看涨期权与看跌期权入门","description":"解释加密货币期权的基本要素、看涨期权和看跌期权的盈亏计算、买方与卖方的风险差异，以及期权与双币投资的关系。","related":[["futures-contract","期货合约（Futures Contract）","期货合约是约定在未来以特定价格买入或卖出某种资产的标准化协议，在加密货币交易所中通常不交割实物币，而是用保证金结算盈亏。"],["hedging","对冲（Hedging）","对冲是建立一个与现有持仓方向相反或相关的仓位，用来抵消部分价格波动风险的做法，例如持有现货的同时开合约空单。"],["volatility","波动率（Volatility）","波动率是衡量资产价格在一段时间内上下变动幅度的指标，波动率越高，价格涨跌越剧烈，加密货币通常远高于股票和外汇。"],["dual-investment","双币投资（Dual investment）","双币投资是一种结构化理财产品：你选择目标价格和期限并获得较高的约定收益，到期时根据结算价与目标价的关系，用原币种或另一种币种连本带息结算。"]],"lesson":null,"coin":null,"tool":"/topics/derivatives","cta":false},"custodial-wallet":{"slug":"custodial-wallet","cat":"wallets-security","en":"Custodial wallet","contentLocale":"zh-Hans","term":"托管钱包（Custodial Wallet）","aka":["托管账户","中心化钱包","custodial wallet"],"short":"托管钱包是由交易所或其他第三方代为保管私钥的钱包，你通过账户密码登录使用，资产实际由平台控制，便捷但要承担平台风险。","body":[["你在",["中心化交易所","centralized-exchange"],"看到的余额，本质上是平台账本上的记录。链上的币存放在交易所自己控制的",["热钱包","hot-wallet"],"和",["冷钱包","cold-wallet"],"里，你提币时由平台签名转出。好处是忘记密码可以找回、交易方便、不用自己管理",["助记词","seed-phrase"],"。"],"代价是你把控制权交给了平台：平台可能因风控冻结账户、暂停提币，或者在极端情况下因经营失败、被盗而无法兑付。2022 年 11 月 FTX 破产后，很多用户的余额变成了漫长的破产债权，这是托管风险最典型的例子。",["降低托管风险的常见做法：选择公布储备证明、运营透明的交易所；开启",["双重验证","two-factor-authentication"],"和",["提币白名单","withdrawal-whitelist"],"；不把长期不动的大额资产全部放在一家平台；需要时转到自己掌控私钥的非托管钱包或硬件钱包。"]],"example":"假设你在某交易所有 5,000 USDT 和 0.1 BTC，在 App 里随时可以交易和划转，交易所账本记录这些都属于你。如果平台运营正常，你提币时只需支付提币手续费，几分钟到账。但如果平台暂停提币或进入破产程序，这 5,000 USDT 和 0.1 BTC 可能变成待清偿的债权，能拿回多少、什么时候拿回都不确定。","mistakes":["把交易所当作长期保险箱，所有资产都放在同一家平台。","以为交易所余额和自己掌握私钥的链上资产一样安全。","不开启双重验证和提币白名单，账户被盗后资产直接被提走。"],"faq":[{"q":"托管钱包和非托管钱包有什么区别？","a":"托管钱包由平台保管私钥，你通过账户登录使用；非托管钱包由你自己保管私钥和助记词，平台无法替你转账，也无法帮你找回。"},{"q":"交易所的币安全吗？","a":"取决于平台的安全措施、储备情况和经营状况。大型合规交易所风险相对较低，但托管意味着你始终承担平台风险。"}],"title":"托管钱包是什么？交易所托管和自托管区别","description":"解释托管钱包（如交易所账户）的运作方式、便利性与平台风险，以及如何通过储备证明、双重验证和分散存放降低托管风险。","related":[["non-custodial-wallet","非托管钱包（自托管钱包）","非托管钱包是由你自己保管私钥或助记词的钱包，资产的控制权完全在你手里，没有任何平台能替你冻结、挪用或找回。"],["centralized-exchange","中心化交易所（CEX）","中心化交易所（CEX）是由公司运营、托管用户资产并撮合买卖订单的加密货币交易平台，如币安、OKX、Bybit、Bitget。"],["proof-of-reserves","储备金证明（Proof of Reserves）","储备金证明（PoR）是交易所公开证明自己持有的用户资产储备至少等于用户存款总额的做法，通常结合默克尔树和链上地址来让用户自行核验。"],["crypto-wallet","加密钱包（Crypto Wallet）","加密钱包是用来保管私钥、查看余额并签名发送交易的工具，币本身记录在区块链上，钱包保管的是控制这些币的密钥。"]],"lesson":{"id":"E03","slug":"exchange-vs-wallet","ep":3,"title":"币到底在哪：交易所和钱包有什么不同？"},"coin":null,"tool":null,"cta":false},"on-chain-analysis":{"slug":"on-chain-analysis","cat":"onchain","en":"On-chain analysis","contentLocale":"zh-Hans","term":"链上分析（On-chain analysis）","aka":["链上数据分析","链上数据","On-chain"],"short":"链上分析是通过研究区块链上公开记录的转账、地址余额、交易所资金流向等数据，来判断市场参与者行为和资金动向的分析方法。","body":[["公链上的每笔交易都公开可查，这让加密市场拥有传统金融没有的数据来源。常用的链上指标包括：",["交易所净流入/净流出","exchange-netflow"],"、",["巨鲸","whale"],"地址的持仓变化、",["活跃地址数","active-addresses"],"、",["稳定币","stablecoin"],"供应量、",["长期持有","hodl"],"者的成本区间，以及矿工的出货情况等。"],["链上分析和看K线的技术分析互为补充：K线反映价格和",["成交量","trading-volume"],"，链上数据则试图回答“谁在买、谁在卖、币流向哪里”。例如大量BTC从交易所提到冷钱包，常被解读为持有人倾向长期持有；大额稳定币转入交易所，则可能意味着有资金准备买入。"],"需要注意，链上数据需要正确解读。交易所内部的冷热钱包调拨、托管机构的资产迁移，都可能看起来像大额流动；很多交易发生在交易所内部账本上，根本不上链。不同数据平台对地址的标注方法不同，结果也可能有差异。"],"example":"假设某数据平台显示，一周内交易所的BTC总余额从230万枚降到225万枚，减少5万枚；同一周，交易所的稳定币余额增加了20亿美元。初步解读是：一部分BTC被提走，交易所内准备买入的资金在增加。但你进一步查看后发现，其中3万枚是某交易所把币从旧地址迁到新地址，真实净流出只有2万枚，信号强度就要打折扣。","mistakes":["把单一链上指标当成买卖信号，不结合价格、资金费率等其他信息。","不区分交易所内部钱包调拨和真实的用户提币，误读大额转账。","以为链上数据涵盖了全部交易，忽略了中心化交易所内部撮合并不上链。"],"faq":[{"q":"链上分析能预测价格吗？","a":"它不能准确预测价格，只能帮助你理解资金流向和持有人行为。把它作为辅助信息，比单独依赖某一个指标更可靠。"},{"q":"新手从哪些链上指标入手？","a":"可以先看交易所净流入/净流出、稳定币供应变化和活跃地址数，这几个指标含义直观，也容易在公开数据平台上找到。"}],"title":"什么是链上分析？常用链上指标与解读方法","description":"链上分析是什么？了解交易所资金流向、巨鲸地址、活跃地址等常用链上指标的含义，以及解读链上数据时的常见误区。","related":[["exchange-netflow","交易所净流入/净流出（Exchange netflow）","交易所净流入/净流出是指一段时间内转入中心化交易所的某种加密资产数量减去从交易所转出的数量，用来观察资金是在涌向交易所还是离开交易所。"],["whale","巨鲸（Whale）","巨鲸是指持有某种加密资产数量极大的个人或机构地址，他们的买卖或转账规模足以影响市场价格和情绪。"],["active-addresses","活跃地址数（Active addresses）","活跃地址数是指在一定时间内（通常是一天）作为发送方或接收方参与过链上交易的不重复地址数量，常被用来粗略衡量一条区块链的使用热度。"],["block-explorer","区块浏览器（Block explorer）","区块浏览器是一种可以按交易哈希、钱包地址或区块高度查询区块链上公开记录的网站或工具，例如以太坊的Etherscan和波场的Tronscan。"]],"lesson":null,"coin":null,"tool":"/onchain","cta":false},"grid-trading-bot":{"slug":"grid-trading-bot","cat":"exchange-features","en":"Grid trading bot","contentLocale":"zh-Hans","term":"网格交易机器人（Grid trading bot）","aka":["网格交易","网格机器人","网格策略"],"short":"网格交易机器人是在你设定的价格区间内按等距价位自动挂出一组买单和卖单的交易工具，价格每下跌一格就买入、每上涨一格就卖出，赚取震荡中的差价。","body":[["你需要设置价格区间的上下限、网格数量和投入资金，机器人会把区间分成若干格，在每格的价位挂好",["限价单","limit-order"],"。价格在区间内来回波动时，每完成一次“低买高卖”，就锁定一格的利润。主流",["交易所","centralized-exchange"],"都提供现货网格和合约网格。"],"网格适合震荡行情。单边上涨时，机器人会把币逐步卖光，后面的涨幅你就享受不到；单边下跌时，它会持续买入，最终持有一堆亏损的币。价格跌出区间下限后，机器人通常停止交易，你持有的是浮亏的现货仓位。",["设置时要考虑手续费：网格越密，每格利润越薄，频繁成交的挂单/吃单手续费可能吃掉大部分收益。合约网格还叠加了",["杠杆","leverage"],"和",["强平","liquidation"],"风险。"]],"example":["假设ETH在2,000到2,400 USDT之间震荡，你设置8格，每格间距50 ",["USDT","usdt"],"，每格交易0.1 ",["ETH","ethereum"],"。价格从2,200跌到2,150时买入0.1 ETH，再回到2,200时卖出，这一格赚5 USDT，扣除双边0.1%手续费约0.44 USDT，净赚约4.56 USDT。如果这个过程一周重复20次，约赚91 USDT。但若ETH跌破2,000到1,800，机器人持有的0.8 ETH会出现明显浮亏，远超之前赚到的网格利润。"],"mistakes":["在明显单边行情中开网格，结果上涨时过早卖光、下跌时越买越多。","网格设得过密，没算手续费，实际每格几乎不赚钱。","不设区间外的止损，价格跌穿下限后长期持有大额浮亏。"],"faq":[{"q":"网格交易稳赚吗？","a":"不是。网格在区间震荡中能赚取差价，但遇到单边下跌会持续买入并产生浮亏，收益和风险都取决于区间和行情的匹配程度。"},{"q":"网格数量设置多少合适？","a":"取决于区间宽度和手续费率。每格利润至少要明显高于一次买卖的手续费总和，否则成交越多越不划算。"}],"title":"什么是网格交易机器人？原理、收益与风险","description":"网格交易机器人是什么？了解网格策略如何在震荡中低买高卖、区间和格数怎么设置、手续费如何影响收益，以及单边行情的风险。","related":[["dollar-cost-averaging","定投（DCA）","定投（DCA）是按固定周期、用固定金额买入同一资产的策略，不去猜测高低点，借助分批买入摊平成本、降低一次性买在高位的风险。"],["copy-trading","跟单交易（Copy trading）","跟单交易是交易所提供的一种功能，让你选择一位公开交易记录的带单员，按设定的比例或金额自动复制他的开仓和平仓操作。"],["volatility","波动率（Volatility）","波动率是衡量资产价格在一段时间内上下变动幅度的指标，波动率越高，价格涨跌越剧烈，加密货币通常远高于股票和外汇。"],["limit-order","限价单（Limit Order）","限价单是指定价格买入或卖出的订单，只在市场价格达到或优于你设定的价格时才成交，可能部分成交或一直不成交。"]],"lesson":null,"coin":null,"tool":null,"cta":true}});
